package forth

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// action is a single executable operation on the virtual machine.
type action func(*vm) error

// wordDef is a word definition: an ordered list of actions to execute.
//
// References to other words are resolved to a *wordDef pointer at the time a
// definition is compiled. This is what makes redefinition behave correctly:
// a word that referenced an earlier definition keeps pointing at that old
// definition object even after the name is rebound to a new one.
type wordDef struct {
	actions []action
}

// vm is the Forth virtual machine: a data stack plus the word dictionary.
type vm struct {
	stack []int
	dict  map[string]*wordDef
}

// Forth evaluates the given input lines and returns the resulting data stack.
func Forth(input []string) ([]int, error) {
	f := &vm{dict: newDict()}
	for _, line := range input {
		if err := f.runLine(line); err != nil {
			return nil, err
		}
	}
	return f.stack, nil
}

func newDict() map[string]*wordDef {
	return map[string]*wordDef{
		"+":    binaryOp(func(a, b int) (int, error) { return a + b, nil }),
		"-":    binaryOp(func(a, b int) (int, error) { return a - b, nil }),
		"*":    binaryOp(func(a, b int) (int, error) { return a * b, nil }),
		"/": binaryOp(func(a, b int) (int, error) {
			if b == 0 {
				return 0, errors.New("division by zero")
			}
			return a / b, nil
		}),
		"dup": &wordDef{actions: []action{
			func(f *vm) error {
				if len(f.stack) == 0 {
					return errors.New("empty stack")
				}
				return f.push(f.stack[len(f.stack)-1])
			},
		}},
		"drop": &wordDef{actions: []action{
			func(f *vm) error {
				if len(f.stack) == 0 {
					return errors.New("empty stack")
				}
				f.stack = f.stack[:len(f.stack)-1]
				return nil
			},
		}},
		"swap": &wordDef{actions: []action{
			func(f *vm) error {
				if len(f.stack) < 2 {
					return errors.New("not enough values on the stack")
				}
				n := len(f.stack)
				f.stack[n-1], f.stack[n-2] = f.stack[n-2], f.stack[n-1]
				return nil
			},
		}},
		"over": &wordDef{actions: []action{
			func(f *vm) error {
				if len(f.stack) < 2 {
					return errors.New("not enough values on the stack")
				}
				return f.push(f.stack[len(f.stack)-2])
			},
		}},
	}
}

// binaryOp builds a word that pops b then a, applies fn(a, b) and pushes the
// result.
func binaryOp(fn func(a, b int) (int, error)) *wordDef {
	return &wordDef{actions: []action{
		func(f *vm) error {
			b, err := f.pop()
			if err != nil {
				return err
			}
			a, err := f.pop()
			if err != nil {
				return err
			}
			r, err := fn(a, b)
			if err != nil {
				return err
			}
			return f.push(r)
		},
	}}
}

func (f *vm) runLine(line string) error {
	tokens := strings.Fields(line)
	if len(tokens) == 0 {
		return nil
	}
	if tokens[0] == ":" {
		return f.define(tokens)
	}
	return f.exec(tokens)
}

// define compiles a `: name body ;` definition, resolving every word in the
// body against the dictionary as it stands at compile time.
func (f *vm) define(tokens []string) error {
	if len(tokens) < 3 {
		return errors.New("malformed definition")
	}
	name := strings.ToLower(tokens[1])
	if isNumber(tokens[1]) {
		return errors.New("cannot redefine a number")
	}
	semi := -1
	for i, t := range tokens {
		if t == ";" {
			semi = i
			break
		}
	}
	if semi < 2 {
		return errors.New("missing ';' in definition")
	}
	actions, err := f.resolve(tokens[2:semi])
	if err != nil {
		return err
	}
	f.dict[name] = &wordDef{actions: actions}
	return nil
}

// resolve turns a slice of tokens into a slice of actions, binding each word
// token to the definition object it refers to at this moment.
func (f *vm) resolve(tokens []string) ([]action, error) {
	actions := make([]action, 0, len(tokens))
	for _, tok := range tokens {
		if isNumber(tok) {
			n, _ := strconv.Atoi(tok)
			actions = append(actions, func(v *vm) error { return v.push(n) })
		} else {
			key := strings.ToLower(tok)
			def, ok := f.dict[key]
			if !ok {
				return nil, fmt.Errorf("undefined word %q", tok)
			}
			actions = append(actions, func(v *vm) error { return v.run(def) })
		}
	}
	return actions, nil
}

func (f *vm) exec(tokens []string) error {
	for _, tok := range tokens {
		if isNumber(tok) {
			n, _ := strconv.Atoi(tok)
			if err := f.push(n); err != nil {
				return err
			}
		} else {
			key := strings.ToLower(tok)
			def, ok := f.dict[key]
			if !ok {
				return fmt.Errorf("undefined word %q", tok)
			}
			if err := f.run(def); err != nil {
				return err
			}
		}
	}
	return nil
}

func (f *vm) run(def *wordDef) error {
	for _, a := range def.actions {
		if err := a(f); err != nil {
			return err
		}
	}
	return nil
}

func (f *vm) push(n int) error {
	f.stack = append(f.stack, n)
	return nil
}

func (f *vm) pop() (int, error) {
	if len(f.stack) == 0 {
		return 0, errors.New("empty stack")
	}
	n := f.stack[len(f.stack)-1]
	f.stack = f.stack[:len(f.stack)-1]
	return n, nil
}

// isNumber reports whether tok is a (possibly negative) integer literal: an
// optional leading '-' followed by one or more ASCII digits.
func isNumber(tok string) bool {
	if tok == "" {
		return false
	}
	start := 0
	if tok[0] == '-' {
		start = 1
	}
	if start >= len(tok) {
		return false
	}
	for i := start; i < len(tok); i++ {
		if tok[i] < '0' || tok[i] > '9' {
			return false
		}
	}
	return true
}
